const body = $input.first().json.body || {};
const headers = $input.first().json.headers || {};
let isAdmin = false;
if (body.role && body.role.toLowerCase() === 'admin') isAdmin = true;

let hasFile = false;
let mime = '';
let ext = '';
let isImage = false;
let isSpreadsheet = false;
if ($input.first().binary && $input.first().binary.file) {
    hasFile = true;
    mime = ($input.first().binary.file.mimeType || '').toLowerCase();
    ext = ($input.first().binary.file.fileExtension || '').toLowerCase();
    if (mime.includes('image') || ext === 'png' || ext === 'jpg' || ext === 'jpeg') {
        isImage = true;
    } else if (mime.includes('excel') || mime.includes('spreadsheet') || ext === 'xlsx' || ext === 'xls' || ext === 'csv') {
        isSpreadsheet = true;
    }
}

return [{
    json: {
        passes: isAdmin,
        hasFile: hasFile,
        expiryDate: body.expiryDate || 'never',
        title: body.title || 'Untitled Document',
        mime: mime,
        ext: ext,
        isImage: isImage,
        isSpreadsheet: isSpreadsheet
    },
    binary: $input.first().binary
}];

let fullText = '';
for (const item of $input.all()) {
  if (item.json) {
    const line = Object.values(item.json).filter(v => v !== null && v !== undefined && String(v).trim() !== '').join(' | ');
    if (line.trim()) fullText += line + '\n';
  }
}
const authNode = $('Check Auth & Format').first().json;
const title = authNode.title || 'Untitled';
const expiryDate = authNode.expiryDate || 'never';
const textBuffer = Buffer.from(fullText, 'utf8');
return [{
  json: { title: title, expiryDate: expiryDate },
  binary: { text_file: { data: textBuffer.toString('base64'), mimeType: 'text/plain', fileName: 'omni_unified_knowledge.txt' } }
}];

const item = $input.first();
const authNode = $('Check Auth & Format').first().json;
const title = authNode.title || 'Untitled';
const expiryDate = authNode.expiryDate || 'never';
return [{
  json: { title: title, expiryDate: expiryDate },
  binary: { text_file: item.binary.file }
}];

const item = $input.first();
// FIX FOR FILESYSTEM BINARY STORE
const buffer = await this.helpers.getBinaryDataBuffer(0, 'file');
const base64Data = buffer.toString('base64');
const mimeType = item.binary.file.mimeType || 'image/png';

const systemPrompt = `Bạn là công cụ trích xuất văn bản (OCR) siêu việt. Hãy trích xuất chính xác 100% các chữ có trong ảnh. Tuyệt đối không tự tóm tắt, không tự sáng tạo nội dung. Giả định bạn phân tích tờ rơi, trả về dữ liệu JSON chứa 2 field:\n1. "product_name": Tên sản phẩm chính.\n2. "content": Toàn bộ nội dung tờ rơi.`;

return [{ json: {
  model: "openai/gpt-4o-mini",
  response_format: { type: "json_object" },
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: [
        { type: "text", text: "Hãy trích xuất JSON:" },
        { type: "image_url", image_url: { url: 'data:' + mimeType + ';base64,' + base64Data } }
    ] }
  ]
}}];

const text = $input.first().json.choices[0].message.content;
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch(e) {
  parsed = { product_name: 'Unknown', content: text };
}
const productName = parsed.product_name || 'Thông tin hình ảnh';
const rawContent = parsed.content || text;
const textBuffer = Buffer.from(`[ẢNH SẢN PHẨM: ${productName}]\n\n` + rawContent, 'utf8');

const authNode = $('Check Auth & Format').first().json;
const expiryDate = authNode.expiryDate || 'never';

return [{
  json: { title: productName, expiryDate: expiryDate, source_type: 'image_poster' },
  binary: { text_file: { data: textBuffer.toString('base64'), mimeType: 'text/plain', fileName: 'ocr_extracted.txt' } }
}];
